import React, { useContext } from 'react';
import SiteContext from '../../SiteContext';

export default function ArticleTitleList() {
    const context = useContext(SiteContext);
    
    return (
        <div className="article-title-list">
            <h3>All Articles</h3>
            <ul>
                {context.articles.map(article => (
                    <li 
                        key={article.id} 
                        onClick={() => context.goToArticle(article.username, article.id)} 
                        style={{cursor: 'pointer', color: 'blue', textDecoration: 'underline', marginBottom: '8px'}}
                    >
                        {article.title}
                    </li>
                ))}
            </ul>
        </div>
    );
}
